public class Main {
    static int n, m;
    static int[][] direct = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        scanner.nextLine(); // 读取换行符

        String[][] ans = new String[n][m];
        for (int i = 0; i < n; i++) {
            ans[i] = scanner.nextLine().split(" ");
        }
​
        boolean[][] visited = new boolean[n][m];
        List<Pair<Integer, String>> resNode = new ArrayList<>();
​
        // 遍历所有节点
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (ans[i][j].equals("O") && !visited[i][j]) {
                    List<int[]> enter = new ArrayList<>();
                    int res = bfs(ans, visited, i, j, enter);
​
                    if (enter.size() == 1) {
                        resNode.add(new Pair<>(res, enter.get(0)[0] + " " + enter.get(0)[1]));
                    }
                }
            }
        }
​
        if (resNode.isEmpty()) {
            System.out.println("NULL");
        } else if (resNode.size() == 1) {
            System.out.println(resNode.get(0).getValue() + " " + resNode.get(0).getKey());
        } else {
            resNode.sort((a, b) -> b.getKey() - a.getKey());
            if (resNode.get(0).getKey().equals(resNode.get(1).getKey())) {
                System.out.println(resNode.get(0).getKey());
            } else {
                System.out.println(resNode.get(0).getValue() + " " + resNode.get(0).getKey());
            }
        }
    }
​
    // BFS 计算连通区域大小和入口坐标
    private static int bfs(String[][] ans, boolean[][] visited, int x, int y, List<int[]> enter) {
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{x, y});
        visited[x][y] = true;
        int res = 0;
​
        while (!queue.isEmpty()) {
            int[] p = queue.poll();
            int currentX = p[0], currentY = p[1];
            res++;
​
            // 记录入口坐标
            if (currentX == 0 || currentY == 0 || currentX == n - 1 || currentY == m - 1) {
                enter.add(new int[]{currentX, currentY});
            }
​
            // 遍历四个方向
            for (int[] d : direct) {
                int newX = currentX + d[0];
                int newY = currentY + d[1];
                if (newX >= 0 && newX < n && newY >= 0 && newY < m && !visited[newX][newY] && ans[newX][newY].equals("O")) {
                    visited[newX][newY] = true;
                    queue.add(new int[]{newX, newY});
                }
            }
        }
        return res;
    }
​
    static class Pair<K, V> {
        K key;
        V value;
        Pair(K key, V value) {
            this.key = key;
            this.value = value;
        }
        K getKey() { return key; }
        V getValue() { return value; }
    }
}
