package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// 方向数组：左、右、上、下
var directions = [][]int{{0, -1}, {0, 1}, {-1, 0}, {1, 0}}
var n, m int
​
// BFS 遍历连通区域，并返回区域大小和可能的入口点
func bfs(grid [][]string, visited [][]bool, x, y int) (int, []string) {
    queue := [][]int{{x, y}}
    visited[x][y] = true
    count := 0
    var enter []string
​
    for len(queue) > 0 {
        point := queue[0]
        queue = queue[1:]
        curX, curY := point[0], point[1]
        count++
​
        // 记录边界作为入口
        if curX == 0 || curY == 0 || curX == n-1 || curY == m-1 {
            enter = append(enter, fmt.Sprintf("%d %d", curX, curY))
        }
​
        // 遍历四个方向
        for _, d := range directions {
            newX, newY := curX+d[0], curY+d[1]
            if newX >= 0 && newX < n && newY >= 0 && newY < m && !visited[newX][newY] && grid[newX][newY] == "O" {
                visited[newX][newY] = true
                queue = append(queue, []int{newX, newY})
            }
        }
    }
    return count, enter
}
​
func main() {
    // 读取输入
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    firstLine := strings.Split(scanner.Text(), " ")
    n, _ = strconv.Atoi(firstLine[0])
    m, _ = strconv.Atoi(firstLine[1])
​
    // 读取矩阵
    grid := make([][]string, n)
    for i := 0; i < n; i++ {
        scanner.Scan()
        grid[i] = strings.Split(scanner.Text(), " ")
    }
​
    // 访问标记
    visited := make([][]bool, n)
    for i := range visited {
        visited[i] = make([]bool, m)
    }
​
    // 存储符合条件的区域
    var resNode []struct {
        size   int
        coord  string
    }
​
    // 遍历所有点
    for i := 0; i < n; i++ {
        for j := 0; j < m; j++ {
            if grid[i][j] == "O" && !visited[i][j] {
                size, enter := bfs(grid, visited, i, j)
                if len(enter) == 1 {
                    resNode = append(resNode, struct {
                        size   int
                        coord  string
                    }{size, enter[0]})
                }
            }
        }
    }
​
    // 处理输出
    if len(resNode) == 0 {
        fmt.Println("NULL")
        return
    } else if len(resNode) == 1 {
        fmt.Println(resNode[0].coord, resNode[0].size)
        return
    }
​
    // 按区域大小降序排序
    sort.Slice(resNode, func(i, j int) bool {
        return resNode[i].size > resNode[j].size
    })
​
    if resNode[0].size == resNode[1].size {
        fmt.Println(resNode[0].size)
    } else {
        fmt.Println(resNode[0].coord, resNode[0].size)
    }
}
